import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { TEAM_BLUE } from './constants.js';

// =====================================================================
// Settlement ladder
//
// Mirrors the original Populous progression: the more flat, unclaimed land
// surrounds a settlement, the grander it grows. Models come from
// assets/buildings.glb, generated by tools/build_models.py in Blender.
// =====================================================================
export const LEVELS = [
  { name: 'Tent',         capacity: 3  },
  { name: 'Mud hut',      capacity: 4  },
  { name: 'Straw hut',    capacity: 5  },
  { name: 'Wooden hut',   capacity: 6  },
  { name: 'Stone hut',    capacity: 7  },
  { name: 'Wooden house', capacity: 8  },
  { name: 'Stone house',  capacity: 9  },
  { name: 'Small castle', capacity: 11 },
  { name: 'Fort',         capacity: 13 },
  { name: 'Castle',       capacity: 16 },
];

const TEAM_COLORS = {
  1: 0x3a6fd0, // TEAM_BLUE
  2: 0xc83a3a, // TEAM_RED
};

const templates = [];
// Lambert materials shared by every instance, keyed by `${name}:${team}`.
// Only the `team` material actually differs between tribes.
const materials = new Map();

function lambertFor(src, team) {
  const key = src.name === 'team' ? `team:${team}` : src.name;
  let m = materials.get(key);
  if (!m) {
    m = new THREE.MeshLambertMaterial({
      color: src.name === 'team' ? TEAM_COLORS[team] : src.color,
      flatShading: true,
    });
    if (src.name === 'fire') {
      m.emissive.copy(src.color);
      m.emissiveIntensity = 0.8;
    }
    materials.set(key, m);
  }
  return m;
}

export async function loadBuildings(url = 'assets/buildings.glb') {
  const gltf = await new GLTFLoader().loadAsync(url);
  for (let i = 0; i < LEVELS.length; i++) {
    const obj = gltf.scene.getObjectByName(`level_${i}`);
    if (!obj) throw new Error(`buildings.glb is missing level_${i}`);
    templates[i] = obj;
  }
}

// Build an instance of a settlement level for a team. Geometry and
// materials are shared, so callers must not dispose them.
export function makeBuilding(level, team) {
  const root = templates[level].clone();
  root.position.set(0, 0, 0);
  root.traverse(o => {
    if (!o.isMesh) return;
    o.material = lambertFor(o.material, team ?? TEAM_BLUE);
    o.castShadow = true;
    o.receiveShadow = true;
  });
  return root;
}
